///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnDownload
 * @description fn Download 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnDownload = async function () {
    const sbmOptions = {
        id: "tx_fnDownload",
        method: "post",
        action: "/corpgeneral/treasurystk.do",
        ref: "dma_fnDownloadReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fnSearch_ajaxsubmit
 * @description fn Search ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearch_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearch_ajaxsubmit",
        method: "post",
        action: "/corpgeneral/treasurystk.do",
        ref: "dma_fnSearchAjaxsubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkDateValidation
 * @description 표준 API 조합으로 새로 작성한 검사 함수
 * @param {*} a a
 * @param {*} b b
 * @returns {void}
 * @hidden N
 */
scwin.checkDateValidation = function (a, b) { try { return $c.date.compareFromToDate(a, b); } catch (_e) { return true; } };

/**
 * @method
 * @name keyEvent
 * @description key Event 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.keyEvent = async function (e) {
    if ($c.util.getKeyCode(typeof e !== 'undefined' && e ? e : (typeof event !== 'undefined' ? event : undefined)) === 13 || (typeof e !== 'undefined' && e === 13)) {
        if ($c.util.getKeyCode(event) === 13) {
            if (fnAKCKwdSearchCodeType(($c.util.getComponent('AKCKwd')))) {
                await scwin.fnSearchOption();
            }
        }
    }
};

/**
 * @method
 * @name fnInit
 * @description fn Init 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnInit = async function () {
    await scwin.fnOrder("0", "D");
};

/**
 * @method
 * @name fnSearchCorpName
 * @description fn Search Corp Name 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchCorpName = async function () {
    await scwin.fnSearchOption();
};

/**
 * @method
 * @name fnOrder
 * @description fn Order 처리
 * @param {*} mode mode
 * @param {*} stat stat
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnOrder = async function (mode, stat) {
    $c.util.getComponent("dma_fnDownloadReq").set("orderMode", mode);
    $c.util.getComponent("dma_fnDownloadReq").set("orderStat", stat);
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    await scwin.fnSearch();
};

/**
 * @method
 * @name fnSearchOption
 * @description fn Search Option 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchOption = async function () {
    if (($c.util.getComponent('AKCKwd').getValue() == null ? '' : String($c.util.getComponent('AKCKwd').getValue())) === '') {
        await scwin.fnInit();
    } else {
        scwin.fnSearchCorpBasicInfo();
    }
};

/**
 * @method
 * @name fCheckDateYear
 * @description f Check Date Year 처리
 * @param {*} pDate2 pDate2
 * @returns {void}
 * @hidden N
 */
scwin.fCheckDateYear = function (pDate2) {
    const pDate = $c.num.unFormatNumber(pDate2);
    const vDateYear = pDate.substring(0, 4);
    if ((vDateYear) < 2012) {
        return false;
    }
    return true;
};

/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch = async function () {
    if (!$c.date.isDate($c.util.getComponent('cal_fromDate').getValue())) {
        await $c.win.alert("시작일자 형식이 틀립니다");
        return;
    }
    if (!scwin.fCheckDateYear($c.util.getComponent('cal_fromDate').getValue())) {
        $c.util.getComponent('cal_fromDate').setValue('2012-01-01');
        await $c.win.alert("2012년 데이터부터 조회 가능합니다");
        return;
    }
    if (!$c.date.isDate($c.util.getComponent('cal_toDate').getValue())) {
        await $c.win.alert("종료일자 형식이 틀립니다");
        return;
    }
    if (scwin.checkDateValidation($c.util.getComponent('cal_fromDate'), $c.util.getComponent('cal_toDate')) === false) {
        return;
    }
    if ($c.date.addYear($c.util.getComponent('cal_fromDate').getValue(), 3) < $c.date.addYear($c.util.getComponent('cal_toDate').getValue(), 0)) {
        await $c.win.alert("조회기간은 3년 이내만 가능합니다.");
        return;
    }
    const srchgubun = ($c.util.getComponent("dma_fnDownloadReq").get("searchGubun") || '');
    if (srchgubun === "decl") {
        $c.util.getComponent("dma_fnDownloadReq").set("method", "searchDeclOfTreasuryStkAcqDisp");
    } else {
        if (srchgubun === "appl") {
            $c.util.getComponent("dma_fnDownloadReq").set("method", "searchApplOfTreasuryStkAcqDisp");
        } else {
            if (srchgubun === "trd") {
                $c.util.getComponent("dma_fnDownloadReq").set("method", "searchTrdOfTreasuryStkAcqDisp");
            } else {
                if (srchgubun === "trddetail") {
                    $c.util.getComponent("dma_fnDownloadReq").set("method", "searchTrdDetailOfTreasuryStkAcqDisp");
                }
            }
        }
    }
    scwin.fnClearCheck();
    if ($c.util.getComponent("ipt_currentPageSize").getValue() != null) {
        $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", $c.util.getComponent("ipt_currentPageSize").getValue());
    }
    await scwin.tx_fnSearch_ajaxsubmit();
};

/**
 * @method
