/**
 * @method
 * @name fnSetCorpBasicInfo
 * @description fn Set Corp Basic Info 처리
 * @param {*} items items
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSetCorpBasicInfo = async function (items) {
    if (items == null) {
        const val = ($c.util.getComponent("dma_fnDownloadReq").get("searchCodeType") || '');
        if (val === "number") {
            await $c.win.alert("조회한 종목코드가 존재하지 않습니다.");
        } else {
            await $c.win.alert("조회한 회사명이 존재하지 않습니다.");
        }
        $c.util.getComponent("dma_fnDownloadReq").set("isurCd", "");
        $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", "");
        $c.util.getComponent('AKCKwd').setValue("");
        $c.util.getComponent("AKCKwd").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
    } else {
        const isurcd = items.isurcd;
        const repisucd = items.repisucd;
        const repisusrtcd = items.repisusrtcd;
        const comabbr = items.comabbrv;
        $c.util.getComponent("dma_fnDownloadReq").set("isurCd", isurcd);
        $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", repisusrtcd);
        $c.util.getComponent('AKCKwd').setValue(comabbr);
        await scwin.fnInit();
    }
};

/**
 * @method
 * @name fnTabView
 * @description fn Tab View 처리
 * @param {Number} idx idx
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnTabView = async function (idx) {
    $(document).find("li[id=tabView]").each(function(index) {
            if (idx === index) {
                if (!$(this).hasClass("active")) {
                    $(this).addClass("active");
                }
            } else {
                if ($(this).hasClass("active")) {
                    $(this).removeClass("active");
                }
            }
    });
    let valSearchGubun = "";
    if (idx === "0") {
        valSearchGubun = "decl";
    } else {
        if (idx === "1") {
            valSearchGubun = "appl";
        } else {
            if (idx === "2") {
                valSearchGubun = "trd";
            }
        }
    }
    $c.util.getComponent("dma_fnDownloadReq").set("searchGubun", valSearchGubun);
    scwin.fnChangeStateOfAcqDispGubun();
    await scwin.fnInit();
};

/**
 * @method
 * @name fnChangeStateOfAcqDispGubun
 * @description fn Change State Of Acq Disp Gubun 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnChangeStateOfAcqDispGubun = function () {
    const selMarketType = $("#searchForm").find("input:radio[name=rd_marketType]:checked").val();
    let kosdaqmktchecked = false;
    let konexmktchecked = false;
    if (selMarketType === 'stock') {

    } else {
        if (selMarketType === 'kosdaq') {
            kosdaqmktchecked = true;
        } else {
            if (selMarketType === 'konex') {
                konexmktchecked = true;
            }
        }
    }
    const srchgubun = ($c.util.getComponent("dma_fnDownloadReq").get("searchGubun") || '');
    const trstkGubun = $("#searchForm").find("select[name=trstkGubun]").val();
    if ((kosdaqmktchecked === true || konexmktchecked === true) && srchgubun === "decl" && trstkGubun === "T") {
        $("#searchForm").find("select[name=slc_acqDispGubun] option:first").attr("selected", "selected");
        $("#searchForm").find("select[name=slc_acqDispGubun]").attr("disabled", "disabled");
    } else {
        $("#searchForm").find("select[name=slc_acqDispGubun]").removeAttr("disabled");
    }
};

