/**
 * @method
 * @name fnClearCheck
 * @description fn Clear Check 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnClearCheck = function () {
    if (($c.util.getComponent('AKCKwd').getValue() == null ? '' : String($c.util.getComponent('AKCKwd').getValue())) === '') {
        $c.util.getComponent("dma_fnDownloadReq").set("isurCd", "");
        $c.util.getComponent("dma_fnDownloadReq").set("repIsuCd", "");
        $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", "");
    }
};

